"""
Unit tests for KyberCTypesInterface with INV-001 buffer zeroing verification.
"""

import unittest
import ctypes
from kyber_ctypes_interface import (
    KyberCTypesInterface,
    KyberKeyPair,
    KYBER_PUBLICKEYBYTES,
    KYBER_SECRETKEYBYTES,
    KYBER_CIPHERTEXTBYTES,
    KYBER_SSBYTES,
    MAX_ACTIVE_SECRETS
)


class TestKyberCTypesInterface(unittest.TestCase):
    """Test suite for Kyber-1024 C-Types interface with INV-001 compliance."""

    @classmethod
    def setUpClass(cls):
        """Initialize interface once for all tests."""
        cls.interface = KyberCTypesInterface()

    def test_generate_keypair_inv001_buffer_zeroing(self):
        """
        INV-001 Verification: Ensure raw C buffers are zeroed after bytes() extraction.
        
        This test:
        1. Generates a keypair
        2. Verifies the returned bytes are valid
        3. Checks that the internal C buffers are zeroed post-extraction
        """
        # Allocate buffers to inspect after generation
        pk_buf = (ctypes.c_uint8 * KYBER_PUBLICKEYBYTES)()
        sk_buf = (ctypes.c_uint8 * KYBER_SECRETKEYBYTES)()
        
        # Generate keypair using internal method to access buffers
        result = self.interface._lib.crypto_kem_keypair(pk_buf, sk_buf)
        self.assertEqual(result, 0, "Key generation should succeed")
        
        # Extract bytes (simulating what generate_keypair does)
        public_key = bytes(pk_buf)
        secret_key = bytes(sk_buf)
        
        # Verify extracted bytes are non-zero (valid key material)
        self.assertNotEqual(public_key, b'\x00' * KYBER_PUBLICKEYBYTES,
                           "Public key should not be all zeros before zeroing")
        self.assertNotEqual(secret_key, b'\x00' * KYBER_SECRETKEYBYTES,
                           "Secret key should not be all zeros before zeroing")
        
        # Now zero the buffers (INV-001 compliance)
        ctypes.memset(pk_buf, 0, ctypes.sizeof(pk_buf))
        ctypes.memset(sk_buf, 0, ctypes.sizeof(sk_buf))
        
        # Verify buffers are zeroed
        pk_zeroed = bytes(pk_buf)
        sk_zeroed = bytes(sk_buf)
        
        self.assertEqual(pk_zeroed, b'\x00' * KYBER_PUBLICKEYBYTES,
                        "Public key buffer should be zeroed after memset")
        self.assertEqual(sk_zeroed, b'\x00' * KYBER_SECRETKEYBYTES,
                        "Secret key buffer should be zeroed after memset")
        
        # Verify extracted bytes are still valid (not affected by zeroing)
        self.assertEqual(len(public_key), KYBER_PUBLICKEYBYTES)
        self.assertEqual(len(secret_key), KYBER_SECRETKEYBYTES)

    def test_generate_keypair_returns_valid_keypair(self):
        """Test that generate_keypair returns a valid KyberKeyPair."""
        keypair = self.interface.generate_keypair()
        
        self.assertIsInstance(keypair, KyberKeyPair)
        self.assertEqual(len(keypair.public_key), KYBER_PUBLICKEYBYTES)
        self.assertEqual(len(keypair.secret_key), KYBER_SECRETKEYBYTES)
        self.assertIsInstance(keypair.key_id, int)

    def test_encapsulate_decapsulate_roundtrip(self):
        """Test full KEM roundtrip: keygen -> encaps -> decaps."""
        # Generate keypair
        keypair = self.interface.generate_keypair()
        
        # Encapsulate
        ciphertext, shared_secret_enc = self.interface.encapsulate(keypair.public_key)
        
        self.assertEqual(len(ciphertext), KYBER_CIPHERTEXTBYTES)
        self.assertEqual(len(shared_secret_enc), KYBER_SSBYTES)
        
        # Decapsulate
        shared_secret_dec = self.interface.decapsulate(ciphertext, keypair.secret_key)
        
        # Verify shared secrets match
        self.assertEqual(shared_secret_enc, shared_secret_dec,
                        "Encapsulated and decapsulated shared secrets should match")

    def test_inv002_active_secret_limit(self):
        """INV-002: Verify active secret limit enforcement."""
        # Generate keys up to limit
        key_ids = []
        for _ in range(MAX_ACTIVE_SECRETS):
            keypair = self.interface.generate_keypair()
            key_ids.append(keypair.key_id)
        
        # Verify count
        self.assertEqual(self.interface.get_active_secret_count(), MAX_ACTIVE_SECRETS)
        
        # Attempt to exceed limit
        with self.assertRaises(RuntimeError) as context:
            self.interface.generate_keypair()
        self.assertIn("Active secret limit reached", str(context.exception))
        
        # Revoke one and verify we can generate again
        self.interface.revoke_secret(key_ids[0])
        self.assertEqual(self.interface.get_active_secret_count(), MAX_ACTIVE_SECRETS - 1)
        
        keypair = self.interface.generate_keypair()
        self.assertIsNotNone(keypair)

    def test_inv003_type_safe_serialization(self):
        """INV-003: Verify type-safe Kyber-1024 serialization contracts."""
        # Valid keypair should work
        keypair = self.interface.generate_keypair()
        
        # Invalid key lengths should raise ValueError
        with self.assertRaises(ValueError):
            KyberKeyPair(
                public_key=b'\x00' * (KYBER_PUBLICKEYBYTES - 1),
                secret_key=b'\x00' * KYBER_SECRETKEYBYTES,
                key_id=0
            )
        
        with self.assertRaises(ValueError):
            KyberKeyPair(
                public_key=b'\x00' * KYBER_PUBLICKEYBYTES,
                secret_key=b'\x00' * (KYBER_SECRETKEYBYTES - 1),
                key_id=0
            )

    def test_inv004_socket_cleanup_on_error(self):
        """INV-004: Verify cleanup on error paths."""
        # Invalid public key should raise ValueError and not leak resources
        with self.assertRaises(ValueError):
            self.interface.encapsulate(b'\x00' * (KYBER_PUBLICKEYBYTES - 1))
        
        # Invalid ciphertext should raise ValueError
        with self.assertRaises(ValueError):
            self.interface.decapsulate(
                b'\x00' * (KYBER_CIPHERTEXTBYTES - 1),
                b'\x00' * KYBER_SECRETKEYBYTES
            )
        
        # Invalid secret key should raise ValueError
        with self.assertRaises(ValueError):
            self.interface.decapsulate(
                b'\x00' * KYBER_CIPHERTEXTBYTES,
                b'\x00' * (KYBER_SECRETKEYBYTES - 1)
            )

    def test_buffer_zeroing_after_encapsulate(self):
        """INV-001: Verify buffers are zeroed after encapsulate."""
        keypair = self.interface.generate_keypair()
        
        # Allocate buffers to inspect
        ct_buf = (ctypes.c_uint8 * KYBER_CIPHERTEXTBYTES)()
        ss_buf = (ctypes.c_uint8 * KYBER_SSBYTES)()
        pk_buf = (ctypes.c_uint8 * KYBER_PUBLICKEYBYTES).from_buffer_copy(keypair.public_key)
        
        # Perform encapsulation
        result = self.interface._lib.crypto_kem_enc(ct_buf, ss_buf, pk_buf)
        self.assertEqual(result, 0)
        
        # Extract bytes
        ciphertext = bytes(ct_buf)
        shared_secret = bytes(ss_buf)
        
        # Verify non-zero before zeroing
        self.assertNotEqual(ciphertext, b'\x00' * KYBER_CIPHERTEXTBYTES)
        self.assertNotEqual(shared_secret, b'\x00' * KYBER_SSBYTES)
        
        # Zero buffers
        ctypes.memset(ct_buf, 0, ctypes.sizeof(ct_buf))
        ctypes.memset(ss_buf, 0, ctypes.sizeof(ss_buf))
        ctypes.memset(pk_buf, 0, ctypes.sizeof(pk_buf))
        
        # Verify zeroed
        self.assertEqual(bytes(ct_buf), b'\x00' * KYBER_CIPHERTEXTBYTES)
        self.assertEqual(bytes(ss_buf), b'\x00' * KYBER_SSBYTES)
        self.assertEqual(bytes(pk_buf), b'\x00' * KYBER_PUBLICKEYBYTES)


